query:
SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Curry-Howard correspondence"@en "Galilean transformation"@en "Newton's laws"@en "Newton's second law"@en "acceleration"@en "action and reaction"@en "angular acceleration"@en "angular momentum"@en "angular velocity"@en "beta reduction"@en "center of gravity"@en "center of mass"@en "centrifugal force"@en "centripetal force"@en "classical logic"@en "coercion"@en "collision"@en "conservation of energy"@en "conservation of momentum"@en "constructive mathematics"@en "curry-howard correspondence"@en "definitional equality"@en "displacement"@en "distance"@en "elastic collision"@en "energy"@en "eta expansion"@en "explicit argument"@en "force"@en "free fall"@en "friction"@en "galilean transformation"@en "goal"@en "gravitational field"@en "gravitational potential"@en "gravity"@en "implicit argument"@en "impulse"@en "inelastic collision"@en "inertia"@en "inertial frame"@en "instance"@en "kinetic energy"@en "kinetic friction"@en "lambda calculus"@en "law of excluded middle"@en "local context"@en "mass"@en "mechanical energy"@en "moment of inertia"@en "momentum"@en "namespace"@en "newton's laws"@en "newton's second law"@en "non-inertial frame"@en "normal force"@en "normal form"@en "notation"@en "position"@en "potential energy"@en "power"@en "projectile motion"@en "proof irrelevance"@en "propositional equality"@en "propositions as types"@en "quotient type"@en "recursive definition"@en "reference frame"@en "rigid body"@en "rotational motion"@en "speed"@en "static friction"@en "structure"@en "subgoal"@en "tension"@en "termination"@en "torque"@en "trajectory"@en "translational motion"@en "universe"@en "universe polymorphism"@en "velocity"@en "well-founded relation"@en "work"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
